#!/bin/sh
# Compile check of src/ against the shared 6.12 BSP output (read-only use of bsp612/out/lahaina).
#   ./build.sh            -> src/nfc_sec.ko (log: build.log)
#   ./build.sh clean
# src/ is generated by ./port.sh from the phone's read-only 5.4 source; after editing src/ by
# hand, regenerate the patch with ./mkpatch.sh (see README.md).
set -e
P=$(cd "$(dirname "$0")" && git rev-parse --show-toplevel)
HERE=$P/drivers612/nfc
[ -f "$HERE/src/sec_nfc.c" ] || { echo "src/ missing: run ./port.sh first"; exit 1; }
cp "$HERE/Kbuild" "$HERE/src/Kbuild"
KBUILD_BUILD_USER=android-build KBUILD_BUILD_HOST=localhost \
make -C $P/bsp612/kernel ARCH=arm64 \
	LLVM=${ANDROID_TREE:-$HOME/android}/prebuilts/clang/host/linux-x86/clang-r547379/bin/ \
	O=$P/bsp612/out/lahaina M=$HERE/src \
	-j16 "${@:-modules}" 2>&1 | tee "$HERE/build.log"
# make's status is lost in the pipe: fail on any compiler/modpost error or warning.
! grep -E ' error:| warning:|WARNING:|ERROR:|Error ' "$HERE/build.log"
